DataFlow.Transform:

// Math.Round on a decimal uses banker's rounding (round half to even) by default.
decimal cad = row.Currency == "USD" ? Math.Round(row.Amount * 1.35m, 2) : row.Amount;
decimal fee = 0m;
if (row.TxnType == "WDR" && row.Channel == "ATM" && cad > 500m) fee = 2.00m;
if (row.TxnType == "WIRE") fee = Math.Max(5m, Math.Min(25m, Math.Round(cad * 0.001m, 2)));
